#!/usr/bin/env node
/**
 * iOS App-target Capacitor plugins — single list + registration contract.
 *
 * App-target plugins are Swift `CAPBridgedPlugin` classes compiled into the App target (not npm
 * packages). They are registered in native code — `DibayRootBridgeViewController.makeAppTargetPlugins()`
 * via `bridge.registerPluginInstance` in `capacitorDidLoad()` — the same model as Android
 * `MainActivity.registerPlugin`.
 *
 * They must NOT be listed in `ios/App/App/capacitor.config.json` → `packageClassList`:
 * - that file is regenerated by the Capacitor CLI on every `cap copy` / `cap update` / `cap sync`
 *   from node_modules only, so any App-target entry is lost on the next sync (2026-10-01:
 *   a plain `cap sync` shipped an iOS build without NativeOAuthLauncher → Google login failed);
 * - a class in both places would be loaded twice (`registerPluginInstance` overrides + load()).
 *
 * Run: `node scripts/ios-app-target-plugins.mjs` → exits 1 when the contract is broken.
 * @see docs/ios-capacitor-app-target-package-classlist.md
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const IOS_CAP_CONFIG_REL = "ios/App/App/capacitor.config.json";
export const IOS_ROOT_BRIDGE_REL = "ios/App/App/DibayRootBridgeViewController.swift";

/** Call outgoing HARD LOCK subset — see docs/dibay-call-ios-outgoing-package-classlist-hard-lock.md */
export const IOS_CALL_OUTGOING_PLUGIN_CLASSES = [
  "NativeCallServicePlugin",
  "DibayVoipCallPlugin",
  "DibayCallPipPlugin",
];

/** Auth App-target plugins — Apple/Kakao native + Google/Kakao web OAuth launcher */
export const IOS_AUTH_PLUGIN_CLASSES = [
  "NativeAppleAuthPlugin",
  "NativeKakaoAuthPlugin",
  "NativeOAuthLauncherPlugin",
];

/** Delivery / media App-target plugins */
export const IOS_DELIVERY_PLUGIN_CLASSES = [
  "DibayAppIconDeliveryPlugin",
  "MessengerPhotoLibraryPlugin",
];

/** Device identity — not Call / Auth / Delivery */
export const IOS_DEVICE_PLUGIN_CLASSES = ["DibayDeviceClassPlugin"];

/** Every App-target plugin. Domain contracts reference subsets; there is no second list. */
export const IOS_APP_TARGET_PLUGIN_CLASSES = [
  ...IOS_CALL_OUTGOING_PLUGIN_CLASSES,
  ...IOS_AUTH_PLUGIN_CLASSES,
  ...IOS_DELIVERY_PLUGIN_CLASSES,
  ...IOS_DEVICE_PLUGIN_CLASSES,
];

/** Body of `static func makeAppTargetPlugins()` in the root bridge VC ("" when absent). */
export function readNativeAppTargetRegistration(root = ROOT) {
  const src = fs.readFileSync(path.join(root, IOS_ROOT_BRIDGE_REL), "utf8");
  const start = src.indexOf("static func makeAppTargetPlugins()");
  if (start < 0) return { src, body: "" };
  const open = src.indexOf("{", start);
  const close = src.indexOf("\n  }", open);
  return { src, body: open < 0 || close < 0 ? "" : src.slice(open, close) };
}

/** Contract failures for the given class subset (default: all App-target plugins). */
export function checkIosAppTargetPluginRegistration(classes = IOS_APP_TARGET_PLUGIN_CLASSES, root = ROOT) {
  const failures = [];
  const { src, body } = readNativeAppTargetRegistration(root);
  if (!body) {
    failures.push(`${IOS_ROOT_BRIDGE_REL} must define static func makeAppTargetPlugins()`);
  }
  if (!/override func capacitorDidLoad\(\)[\s\S]*?registerAppTargetPlugins\(\)/.test(src)) {
    failures.push(`${IOS_ROOT_BRIDGE_REL} capacitorDidLoad() must call registerAppTargetPlugins()`);
  }
  if (!src.includes("bridge.registerPluginInstance(plugin)")) {
    failures.push(`${IOS_ROOT_BRIDGE_REL} must register via bridge.registerPluginInstance`);
  }
  for (const cls of classes) {
    if (!body.includes(`${cls}()`)) {
      failures.push(`${IOS_ROOT_BRIDGE_REL} makeAppTargetPlugins() must register ${cls}`);
    }
  }
  let classList = [];
  try {
    const parsed = JSON.parse(fs.readFileSync(path.join(root, IOS_CAP_CONFIG_REL), "utf8"));
    classList = Array.isArray(parsed.packageClassList) ? parsed.packageClassList : [];
  } catch (err) {
    failures.push(`${IOS_CAP_CONFIG_REL} must be valid JSON (${err instanceof Error ? err.message : String(err)})`);
  }
  for (const cls of classes) {
    if (classList.includes(cls)) {
      failures.push(
        `${IOS_CAP_CONFIG_REL} packageClassList must not list App-target ${cls} (registered natively; CLI-generated file)`,
      );
    }
  }
  return { failures, classList };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { failures, classList } = checkIosAppTargetPluginRegistration();
  if (failures.length > 0) {
    console.error("[ios-app-target-plugins] FAIL");
    for (const f of failures) console.error(`  - ${f}`);
    process.exit(1);
  }
  console.log(
    `[ios-app-target-plugins] PASS — ${IOS_APP_TARGET_PLUGIN_CLASSES.length} registered natively; packageClassList (${classList.length}) is CLI-generated only`,
  );
}
